164:   const tokens = buildMeaningfulQuery(query).split(/\s+/).map((token) => token.replace(/[’'].*$/, '').replace(/^[^\p{L}\p{N}]+|[^\p{L}\p{N}]+$/gu, ''));
165:   const useful = tokens.filter((token) => {
166:     const normalized = token.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i');
167:     return token && !stopWords.has(normalized) && !/^(?:edecek|ediyor|etti|acikladi|duyurdu)$/.test(normalized);
168:   });
169:   const priority = (token) => {
170:     const normalized = token.toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/ı/g, 'i');
171:     if (normalized === 'nato') return 100;
172:     if (/^zirve/.test(normalized)) return 90;
173:     if (normalized === 'trump') return 80;
174:     if (normalized === 'turkiye') return 70;
175:     return Math.min(token.length, 20);
176:   };
177:   const limit = useful.length > 4 ? 4 : Math.max(1, useful.length - 1);
178:   return useful.map((token, index) => ({ token, index }))
179:     .sort((a, b) => priority(b.token) - priority(a.token) || a.index - b.index)
180:     .slice(0, limit)
181:     .map(({ token }) => token)
182:     .join(' ');
