160:     function historySearchMatches(rawText) {
161:       const normalized = rawText.toLocaleLowerCase("tr-TR").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/ı/g, "i");
162:       const stopWords = new Set(["tarih", "tarihi", "tarihce", "ozet", "ozetle", "liste", "tablo", "soru", "sor", "yaz", "hikaye", "senaryo", "sinav", "test", "hakkinda", "bilgi", "goster", "ver", "bir", "icin", "ve", "detay"]);
163:       const terms = normalized.split(/[^a-z0-9çğıöşü]+/i).filter(t => t && !stopWords.has(t));
164:       const matches = state.historyItems.filter(h => {
